std::string markdownToHtml(const std::string& inputMarkdown) {

  // 1. Create a Boost Markdown parser context with HTML output options
  boost::variant<std::string> htmlContent; // Hold the generated HTML
  md_parser context{make_str_parser()};    // Parse input with HTML tags
  context.enable_section_ids();             // Allow auto IDs for headings
  context.enable_inline_tables();           // Support Markdown tables

  // 2. Apply custom rules for HTML conversion using visitor callbacks
  auto md_to_html = make_html_renderer(
        [](const md_parser::section& section) {      // For headings
            std::ostringstream<char> title_id;       // Generate ID for <hX>
            title_id << "title" << section.level;   // Append level number
            return "<" + section.type + " id=\"" + title_id.str() + "\">" +
                   htmlContent.append_visitor(section.content); // Recursive
        },
        [](const md_parser::emphasis& text) {        // For italics/emphasis
          return "<em>" + htmlContent.append_visitor(text) + "</em>";
        },
        // More rules for bold, links, images, lists, code blocks, etc.

        // Generic callback to handle remaining Markdown elements
        [](const md_parser::fragment& fragment) {
            return htmlContent.append_visitor(fragment); // Append all content
        }
    );

  3. Parse Markdown input and apply the HTML rendering rules
  parse(md_to_html, inputMarkdown); // Feed the parser context and input

  // 4. Extract the final HTML string from the variant holder
  std::string htmlResult = boost::get<std::string>(htmlContent);
  htmlResult.erase(0, htmlResult.find_first_not_of("\n")); // Trim leading whitespace

  return htmlResult; // Return HTML formatted string
}
