function checkPrimeAndPrint(numbersArray) {
  // Validate input: array with exactly 5 numbers
  if (numbersArray.length !== 5 || !Array.isArray(numbersArray)) {
    console.error("Invalid input. Please provide an array of exactly 5 numbers.");
    return;  // Terminate with feedback if input validation fails
  }

  // Iterate over each number in the array and check for primality
  for (const num of numbersArray) {
    if (isPrimeNumber(num)) {  // Define isPrimeNumber function below
      console.log(num + " is a prime number.");
    }
  }

  /** Helper function to efficiently verify prime status */
  function isPrimeNumber(number) {
    // Corner case: 1 is not prime
    if (number <= 1 || number === 2) {
      return number === 2;  // 2 is the first prime
    }
    // Rule: a number is prime if not divisible by any integer from 2 to sqrt(number)
    return Number.isInteger(Math.sqrt(number)) && !anyDivisor(number, 2, Math.sqrt(number) + 1);
  }

  // Helper function to avoid iterating up to sqrt(number) squares
  function anyDivisor(num, startDivisor=2) {
    while (startDivisor <= Math.sqrt(num)) {  // Stop at sqrt to optimize
      if (num % startDivisor === 0) {
        return true;  // Found divisor, not prime
      }
      startDivisor++;
    }
    // If loop ended, number is likely prime and not divisible by up to sqrt+1
    return false;
  }
}
```

